CREATE TABLE conflict_evidence (tenant_id text NOT NULL, run_id uuid NOT NULL, evidence_id uuid NOT NULL, operation_id uuid NOT NULL, event_id uuid NOT NULL, fact_digest text NOT NULL, safe_fact_json text NOT NULL, reason text NOT NULL, PRIMARY KEY(tenant_id,run_id,evidence_id), UNIQUE(tenant_id,run_id,operation_id,event_id,fact_digest), FOREIGN KEY(tenant_id,run_id,operation_id) REFERENCES financial_operations);
